SELECT sum(1) AS sample_count, sum(bs.weight) AS units_count, sum(bs."out.electricity.total.energy_consumption..kwh" * bs.weight) AS "electricity.total.energy_consumption..kwh" FROM comstock_amy2018_r2_2025_md_by_state_and_county_parquet AS bs WHERE bs.applicability = true AND bs.upgrade = 0 AND (bs.bldg_id, bs."in.nhgis_tract_gisjoin", bs.state) IN ((1, 'G0100010020200', 'AL'), (1, 'G0100010020502', 'AL'), (1, 'G0100010020600', 'AL'), (1, 'G0100010020700', 'AL'), (1, 'G0100010020802', 'AL'), (1, 'G0100010021000', 'AL'), (1, 'G0100050950100', 'AL'), (1, 'G0100050950900', 'AL'), (1, 'G0100070010002', 'AL'), (1, 'G0100090050101', 'AL'), (1, 'G0100130952700', 'AL'), (1, 'G0100130952900', 'AL'), (1, 'G0100150000300', 'AL'), (1, 'G0100150000500', 'AL'), (1, 'G0100150000800', 'AL'), (1, 'G0100150001100', 'AL'), (1, 'G0100150001102', 'AL'), (1, 'G0100150001600', 'AL'), (1, 'G0100150002101', 'AL'), (1, 'G0100150002103', 'AL')) AND bs.state = 'CO'